'use strict';

// MODULES //

var isRowMajor = require( '@stdlib/ndarray/base/assert/is-row-major' );
var dfill = require( '@stdlib/blas/ext/base/dfill' ).ndarray;
var dscal = require( '@stdlib/blas/base/dscal' ).ndarray;
var max = require( '@stdlib/math/base/special/max' );


// MAIN //

/**
* Performs the matrix-vector operation `y = α*A*x + β*y` where `α` and `β` are scalars, `x` and `y` are `N` element vectors, and `A` is an `N` by `N` symmetric band matrix, with `K` super-diagonals.
*
* @param {string} uplo - specifies whether the upper or lower triangular part of the symmetric matrix `A` should be referenced
* @param {NonNegativeInteger} N - number of elements along each dimension of `A`
* @param {NonNegativeInteger} K - number of super-diagonals of the matrix `A`
* @param {number} alpha - scalar constant
* @param {Float64Array} A - matrix
* @param {integer} strideA1 - stride of the first dimension of `A`
* @param {integer} strideA2 - stride of the second dimension of `A`
* @param {NonNegativeInteger} offsetA - starting index for `A`
* @param {Float64Array} x - first input array
* @param {integer} strideX - `x` stride length
* @param {NonNegativeInteger} offsetX - starting `x` index
* @param {number} beta - scalar constant
* @param {Float64Array} y - second input array
* @param {integer} strideY - `y` stride length
* @param {NonNegativeInteger} offsetY - starting `y` index
* @returns {Float64Array} `y`
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1.0, 2.0, 4.0, 3.0, 5.0, 0.0 ] );
* var x = new Float64Array( [ 1.0, 2.0, 3.0 ] );
* var y = new Float64Array( [ 0.0, 0.0, 0.0 ] );
*
* dsbmv( 'lower', 3, 1, 1.0, A, 2, 1, 0, x, 1, 0, 0.0, y, 1, 0 );
* // y => <Float64Array>[ 10.0, 25.0, 10.0 ]
*/
function dsbmv( uplo, N, K, alpha, A, strideA1, strideA2, offsetA, x, strideX, offsetX, beta, y, strideY, offsetY ) { // eslint-disable-line max-params, max-len
	var tmp1;
	var tmp2;
	var isrm;
	var jmin;
	var sa0;
	var sa1;
	var oa2;
	var tmp;
	var ia;
	var ix;
	var iy;
	var jx;
	var jy;
	var ox;
	var oy;
	var oa;
	var i;
	var j;

	isrm = isRowMajor( [ strideA1, strideA2 ] );
	if ( isrm ) {
		sa0 = strideA2;
		sa1 = strideA1;
	} else {
		sa0 = strideA1;
		sa1 = strideA2;
	}
	// Form: y = β*y
	if ( beta !== 1.0 ) {
		if ( beta === 0.0 ) {
			dfill( N, 0.0, y, strideY, offsetY );
		} else {
			dscal( N, beta, y, strideY, offsetY );
		}
	}
	if ( alpha === 0.0 ) {
		return y;
	}
	ox = offsetX;
	oy = offsetY;

	// Form: y = α*A*x + y
	if (
		( isrm && uplo === 'upper' ) ||
		( !isrm && uplo === 'lower' )
	) {
		ix = ox;
		iy = oy;
		for ( i = 0; i < N; i++ ) {
			tmp1 = alpha * x[ ix ];
			tmp2 = 0.0;
			jmin = max( 0, i - K );
			jx = ox + ( jmin * strideX );
			jy = oy + ( jmin * strideY );
			ia = offsetA + (i * sa1);
			for ( j = jmin; j < i; j++ ) {
				oa = offsetA + ((i - j) * sa0);
				oa2 = oa + (j * sa1);
				y[ jy ] += tmp1 * A[ oa2 ];
				tmp2 += x[ jx ] * A[ oa2 ];
				jx += strideX;
				jy += strideY;
			}
			tmp = alpha * tmp2;
			y[ iy ] += ( tmp1 * A[ ia ] ) + tmp;
			ix += strideX;
			iy += strideY;
		}
		return y;
	}

	// ( order === 'row-major' && uplo === 'lower') || ( order === 'column-major' && uplo === 'upper' )
	if (
		( isrm && uplo === 'lower' ) ||
		( !isrm && uplo === 'upper' )
	) {
		ix = ox;
		iy = oy;
		for ( i = 0; i < N; i++ ) {
			tmp1 = alpha * x[ ix ];
			tmp2 = 0.0;
			jmin = max( 0, i - K );
			jx = ox + ( jmin * strideX );
			jy = oy + ( jmin * strideY );
			for ( j = jmin; j < i; j++ ) {
				oa = offsetA + ((K + j - i) * sa0);
				oa2 = oa + (i * sa1);
				y[ jy ] += tmp1 * A[ oa2 ];
				tmp2 += x[ jx ] * A[ oa2 ];
				jx += strideX;
				jy += strideY;
			}
			oa = offsetA + (K * sa0);
			oa2 = oa + (i * sa1);
			tmp = alpha * tmp2;
			y[ iy ] += ( tmp1 * A[ oa2 ] ) + tmp;
			ix += strideX;
			iy += strideY;
		}
		return y;
	}
}


// EXPORTS //

module.exports = dsbmv;
